// #d9d257 (6a993d711bef8ed807d9d257) — экраны ПОСЛЕ практики без звонка (без расхода OpenAI), на подготовленных кандидатах
// (PREP в support.ts): A — практика пройдена, B — практика оборвана сбоем. Кейсы CALL-011, CALL-012 (вариант без звонка), CALL-013.
// Данных не создаёт. Повторная тех. проверка на A меняет только этап этого подготовленного кандидата.
// Старт попыток/голосовой сессии обрывается страховкой blockCallStarts — официальная попытка не тратится.
import { test, expect } from '../../fixtures';
import {
  Candidate, ONE_TIME, PREP, abs, launchCandidate, tap, scrollWidth, blockCallStarts, expectOfficialScreenNoPractice,
  recheckAndContinue, candidateRow,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — после одноразовой практики, без звонка (#6a993d711bef8ed807d9d257)', () => {
  test('после пройденной практики: ссылка, reload и «חזרה» → повторная тех. проверка ведут только на «פרטי לקוח לשיחה», кнопок практики нет @desktop #6a993d711bef8ed807d9d257', async () => {
    test.setTimeout(4 * 60_000);
    cand = await launchCandidate({ width: 390, height: 844 });
    const { page } = cand;
    const blocked = await blockCallStarts(page);

    // Источник: AC3 / דרישה 2 «אין אפשרות לפתוח אותו מחדש והמסלול ממשיך לניסיון הרשמי».
    await page.goto(abs(PREP.afterPractice.link));
    await expectOfficialScreenNoPractice(page);
    await page.reload();
    await expectOfficialScreenNoPractice(page);

    await tap(page, /חזרה/);
    await expect(page.getByText('בדיקה טכנית').first()).toBeVisible();
    await recheckAndContinue(page);
    await expectOfficialScreenNoPractice(page);

    expect(blocked.start + blocked.voice, 'попыток старта не было').toBe(0);
  });

  test('после обрыва практики: официальная доступна («מוכן, מתחילים»), практика не предлагается, и после reload @desktop #6a993d711bef8ed807d9d257', async () => {
    test.setTimeout(2 * 60_000);
    expect(cand, 'нет браузера из предыдущего теста').toBeTruthy();
    const { page } = cand!;
    // Источник: AC4 «הניסיון הרשמי נותר זמין»; «החזרה מכשל טכני אינה חזרה יזומה על התרגול».
    await page.goto(abs(PREP.afterFailure.link));
    await expectOfficialScreenNoPractice(page);
    await page.reload();
    await expectOfficialScreenNoPractice(page);
  });

  test('экран возврата после обрыва практики (ответ сервера stage=tech_check, reason=practice_technical_failure): «נבדוק שוב את הציוד», «שיחת התרגול נקטעה בגלל תקלה טכנית», «…השיחה הרשמית עדיין זמינה», «התרגול עצמו לא חוזר.»; 390 и 1440 @desktop #6a993d711bef8ed807d9d257', async () => {
    test.setTimeout(2 * 60_000);
    expect(cand, 'нет браузера из предыдущего теста').toBeTruthy();
    const { page } = cand!;
    // Без звонка: настоящий ответ candidate_open_link кандидата B дополняется этапом, который сервер вернул 14.10 сразу
    // после обрыва (stage=tech_check, tech_check_reason=practice_technical_failure). Проверяется только экран.
    await page.route('**/rest/v1/rpc/candidate_open_link', async (route) => {
      if (route.request().method() !== 'POST') return route.continue();
      const res = await route.fetch();
      const body = await res.json();
      return route.fulfill({ response: res, json: { ...body, stage: 'tech_check', tech_check_reason: 'practice_technical_failure' } });
    });
    await page.goto(abs(PREP.afterFailure.link));

    // Источник: AC4 «מוחזר לבדיקה הטכנית עם הסבר, והניסיון הרשמי נותר זמין».
    await expect(page.getByText(ONE_TIME.backTitle)).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(ONE_TIME.backReason)).toBeVisible();
    await expect(page.getByText(ONE_TIME.backNotCounted)).toBeVisible();
    await expect(page.getByText(ONE_TIME.backNoRepeat)).toBeVisible();
    await expect(page.getByRole('button', { name: 'להתחיל בדיקה' })).toBeVisible();
    await expect(page.getByRole('button', { name: /תרגול/ })).toHaveCount(0);
    let w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка на 390').toBeLessThanOrEqual(w.vw);

    await page.setViewportSize({ width: 1440, height: 900 });
    await expect(page.getByText(ONE_TIME.backNoRepeat)).toBeVisible();
    w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка на 1440').toBeLessThanOrEqual(w.vw);
    await page.unroute('**/rest/v1/rpc/candidate_open_link');
  });

  test('бизнес: практика не считается попыткой и не попадает в отчёт — у A и B «בדיקה טכנית החלה», «הושלם» и «דוח» = «—» @desktop #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(2 * 60_000);
    const business = await asUser('business');
    // Источник: AC2 / דרישה 1 «אינו מוערך ואינו מופיע בדוח»; דרישה 4 «אינו נספר כניסיון רשמי».
    for (const c of [PREP.afterPractice, PREP.afterFailure]) {
      const row = await candidateRow(business, c.name);
      await expect(row).toContainText('בדיקה טכנית החלה');
      await expect(row).toContainText('—');
      await expect(row).not.toContainText('הושלמה');
      await expect(row.getByRole('link', { name: /דוח/ })).toHaveCount(0);
    }
  });
});
